   a=[r for r in rows if r['case']==case and r['tool']==tool and r['round']>=0]
   item['tools'][tool]={k:{'median':statistics.median(r[k]for r in a),'min':min(r[k]for r in a),'max':max(r[k]for r in a)}for k in ['wall_ms','cpu_ms','rss_kib']+(['pass_ms']if 'pass_ms'in a[0]else[])}
