from pathlib import Path
from collections import defaultdict
import json,re,hashlib
B=Path('.tmp/dae2-subsecond-20261018/final')
def parse(p):
 edges=defaultdict(lambda:[0,0]);own=defaultdict(int);names={};fn='';cfn=None;calls=0;total=0
 for line in p.read_text().splitlines():
  if line.startswith('events:'):assert line=='events: Ir',line
  if line.startswith('summary:'):total+=int(line.split()[1])
  if line.startswith(('fn=','cfn=')):
   field,value=line.split('=',1);m=re.match(r'\((\d+)\)(?: (.*))?$',value)
   if m:
    key,name=m.groups()
    if name is not None:names[key]=name
    value=names.get(key,key)
   if field=='fn':fn=value;cfn=None
   else:cfn=value
  elif line.startswith('calls='):calls=int(line[6:].split()[0])
  elif re.match(r'^[0-9*+-]',line):
   n=int(line.split()[-1])
   if cfn:edges[fn,cfn][0]+=calls;edges[fn,cfn][1]+=n;cfn=None;calls=0
   else:own[fn]+=n
 return edges,own,total
before,own_before,total_before=parse(Path('.tmp/dae2-subsecond-20261017/final-profile/final.callgrind'))
after,own_after,total_after=parse(B/'profile/final.callgrind')
def select(a,c):
 return ('run__hot__pipeline__apply__module__pass'in a and any(s in c for s in ['dae2__run__module__pass','cleanup__captures','run__hot__pipeline'])) or ('dae2__analyze__function'in a and any(s in c for s in ['cfg__build','local__graph__build__read__sources']))
selected=[{'caller':a,'callee':c,'before':dict(zip(['calls','instructions'],before.get((a,c),(0,0)))),'after':dict(zip(['calls','instructions'],after.get((a,c),(0,0))))}for a,c in sorted(set(before)|set(after))if select(a,c)]
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
assert sha(B/'profile/output.wasm')==sha(B/'traced/large-dae2-optimizing--1-after.wasm')
out={'scope':'large closed-world dae2-optimizing; instruction counts only; recursive inclusive edges must not be added as separate work','before_cli_sha256':sha(B.parent/'baseline.exe'),'after_cli_sha256':sha(B/'final.exe'),'before_total':total_before,'after_total':total_after,'whole_instruction_ratio':total_after/total_before,'selected_call_edges':selected,'after_top_own_instructions':[{'function':f,'instructions':n,'before':own_before.get(f,0)}for f,n in sorted(own_after.items(),key=lambda x:-x[1])[:40]],'output_sha256':sha(B/'profile/output.wasm'),'profile_sha256':sha(B/'profile/final.callgrind')}
(B/'profile/summary.json').write_text(json.dumps(out,indent=2));print(json.dumps({k:v for k,v in out.items()if k!='after_top_own_instructions'},indent=2))
